  def self.deep_freeze(value)
    case value
    when Hash
      value.each { |key, child| deep_freeze(key); deep_freeze(child) }
    when Array
      value.each { |child| deep_freeze(child) }
    end
    value.freeze
  end
  private_class_method :deep_freeze

  CATALOGUE = deep_freeze(RAW_CATALOGUE)
  private_constant :RAW_CATALOGUE

  def self.catalogue
    Marshal.load(Marshal.dump(CATALOGUE))
  end

  # Keep bibliography coverage enforceable. Any future arithmetic claim without
  # a real source should make the service test fail immediately.
  def self.audit_errors
    errors = []
    refs = CATALOGUE.fetch("references")
    units = CATALOGUE.fetch("units")

    refs.each do |reference_id, reference|
      errors << "reference #{reference_id} has no citation" if reference["citation"].to_s.strip.empty?
    end

    CATALOGUE.fetch("periods").each do |period|
      reference_ids = Array(period["reference_ids"])
      errors << "period #{period['id']} has no reference" if period["id"] != "all" && reference_ids.empty?
      reference_ids.each do |reference_id|
        errors << "period #{period['id']} references missing #{reference_id}" unless refs.key?(reference_id)
      end
    end

    CATALOGUE.fetch("standards").each do |standard|
      reference_ids = Array(standard["reference_ids"])
      errors << "standard #{standard['id']} has no reference" if reference_ids.empty?
      reference_ids.each do |reference_id|
        errors << "standard #{standard['id']} references missing #{reference_id}" unless refs.key?(reference_id)
      end
      Array(standard["recommended_units"]).each do |unit_id|
        errors << "standard #{standard['id']} recommends missing unit #{unit_id}" unless units.key?(unit_id)
      end
    end

    units.each do |unit_id, unit|
      Array(unit["input_alias_reference_ids"]).each do |reference_id|
        errors << "unit #{unit_id} input alias references missing #{reference_id}" unless refs.key?(reference_id)
      end
      claims = Array(unit["claims"])
      errors << "unit #{unit_id} has no claims" if claims.empty?
      claims.each_with_index do |claim, index|
        reference_ids = Array(claim["reference_ids"])
        errors << "unit #{unit_id} claim #{index} has no reference" if reference_ids.empty?
        reference_ids.each do |reference_id|
          errors << "unit #{unit_id} claim #{index} references missing #{reference_id}" unless refs.key?(reference_id)
        end
        if claim["status"] != "informational" && claim["factor"].nil?
          errors << "unit #{unit_id} claim #{index} is convertible but has no factor"
        end
      end
    end

    CATALOGUE.fetch("comparison_units").each do |unit|
      reference_ids = Array(unit["reference_ids"])
      errors << "comparison #{unit['id']} has no reference" if reference_ids.empty?
      reference_ids.each do |reference_id|
        errors << "comparison #{unit['id']} references missing #{reference_id}" unless refs.key?(reference_id)
      end
    end

    errors
  end
end
